package com.bank.signaturemanagement.repository; import com.bank.signaturemanagement.entity.SignatureBook; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface SignatureBookRepository extends JpaRepository<SignatureBook,Long>{@Query("select coalesce(max(b.versionNo),0) from SignatureBook b where b.bookYear=:year and b.signatureType=:type")int maxVersion(@Param("year")int year,@Param("type")String type);List<SignatureBook> findByStatus(String status);@Modifying @Query("update SignatureBook b set b.status='ARCHIVED' where b.id<>:currentId and b.status='CURRENT'")int archiveOthers(@Param("currentId")Long currentId);@EntityGraph(attributePaths="generatedBy")List<SignatureBook>findAllByOrderByGeneratedAtDesc();@Override @EntityGraph(attributePaths="generatedBy")Optional<SignatureBook>findById(Long id);}
